    pstmt1.executeUpdate();
    pstmt1.clearParameters();
  }
  conn.commit();
} catch(Exception e) {
  e.printStackTrace();
  try { conn.rollback(); } catch(Exception ex) {}
} finally {
  try {
    rs.close();
    pstmt.close();
    pstmt1.close();
    conn.close();
